firmware:
const int LDR_PIN = 34;
const int LED_PIN = 2;
const int DARK_ABOVE = 2000;
int last = -1;

void setup() {
  Serial.begin(115200);
  pinMode(LED_PIN, OUTPUT);
  digitalWrite(LED_PIN, LOW);
}

void loop() {
  int reading = analogRead(LDR_PIN);
  int dark = reading > DARK_ABOVE ? 1 : 0;
  if (dark != last) {
    digitalWrite(LED_PIN, dark ? HIGH : LOW);
    Serial.println(dark ? "DARK" : "LIGHT");
    last = dark;
  }
  delay(200);
}
